public class Main {
    public static double applyDiscount(double amount, boolean isVip) {
        if (isVip) {
            return amount * 0.80;
        }
        if (amount > 100.0) {
            return amount * 0.90;
        }
        return amount;
    }

    public static void main(String[] args) {
        double finalPrice = applyDiscount(150.0, false);
        System.out.println("Final Price: $" + finalPrice);
    }
}
